t.script:
if ('serviceWorker' in navigator) {
    window.addEventListener('load', function() {
        navigator.serviceWorker.register('/health_pwa/service-worker.js')
            .then(function(registration) {
                console.log('SW registered: ', registration);

                // Check for updates
                registration.addEventListener('updatefound', function() {
                    const newWorker = registration.installing;
                    newWorker.addEventListener('statechange', function() {
                        if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
                            // New content available, notify user
                            if (window.healthPWA && window.healthPWA.notifyUpdate) {
                                window.healthPWA.notifyUpdate();
                            }
                        }
                    });
                });
            })
            .catch(function(registrationError) {
                console.log('SW registration failed: ', registrationError);
            });
    });
}

// PWA Install Prompt
let deferredPrompt;
window.addEventListener('beforeinstallprompt', function(e) {
    e.preventDefault();
    deferredPrompt = e;

    // Show install banner after 3 seconds
    setTimeout(function() {
        if (!localStorage.getItem('pwa-install-dismissed')) {
            document.getElementById('pwa-install-banner').style.display = 'block';
        }
    }, 3000);
});

// Install button handler
document.addEventListener('DOMContentLoaded', function() {
    const installBtn = document.getElementById('pwa-install-btn');
    const dismissBtn = document.getElementById('pwa-dismiss-btn');
    const installBanner = document.getElementById('pwa-install-banner');

    if (installBtn) {
        installBtn.addEventListener('click', async function() {
            if (deferredPrompt) {
                deferredPrompt.prompt();
                const choiceResult = await deferredPrompt.userChoice;
                if (choiceResult.outcome === 'accepted') {
                    console.log('User accepted PWA install');
                }
                deferredPrompt = null;
            }
            installBanner.style.display = 'none';
        });
    }

    if (dismissBtn) {
        dismissBtn.addEventListener('click', function() {
            localStorage.setItem('pwa-install-dismissed', 'true');
            installBanner.style.display = 'none';
        });
    }
});

odoo.template:

// Health PWA Service Worker v1.0.0

const CACHE_NAME = 'health-pwa-v1.0.0';
const OFFLINE_URL = '/health_pwa/offline';
const API_CACHE_NAME = 'health-pwa-api-v1.0.0';

// Files to cache for offline functionality
const STATIC_CACHE_URLS = [
    '/health_pwa',
    '/health_pwa/offline',
    '/health_pwa/static/src/css/app.css',
    '/health_pwa/static/src/css/mobile.css',
    '/health_pwa/static/src/js/app.js',
    '/health_pwa/static/src/js/router.js',
    '/health_pwa/static/icons/icon-192.png',
    'https://unpkg.com/vue@3.4.0/dist/vue.global.prod.js',
    'https://unpkg.com/quasar@2.14.0/dist/quasar.umd.min.js',
    'https://unpkg.com/pouchdb@8.0.0/dist/pouchdb.min.js',
];

// API endpoints to cache
const API_CACHE_PATTERNS = [
    /^\/health_pwa\/api\/patients/,
    /^\/health_pwa\/api\/fso/,
    /^\/health_pwa\/api\/teams/,
    /^\/health_pwa\/api\/user/,
];

// Install event - cache static files
self.addEventListener('install', event => {
    console.log('Service Worker installing...');
    event.waitUntil(
        caches.open(CACHE_NAME)
            .then(cache => {
                console.log('Caching static files');
                return cache.addAll(STATIC_CACHE_URLS);
            })
            .then(() => {
                console.log('Service Worker installed successfully');
                return self.skipWaiting();
            })
            .catch(error => {
                console.error('Service Worker installation failed:', error);
            })
    );
});

// Activate event - clean up old caches
self.addEventListener('activate', event => {
    console.log('Service Worker activating...');
    event.waitUntil(
        caches.keys().then(cacheNames => {
            return Promise.all(
                cacheNames.map(cacheName => {
                    if (cacheName !== CACHE_NAME && cacheName !== API_CACHE_NAME) {
                        console.log('Deleting old cache:', cacheName);
                        return caches.delete(cacheName);
                    }
                })
            );
        }).then(() => {
            console.log('Service Worker activated');
            return self.clients.claim();
        })
    );
});

// Fetch event - handle network requests with caching strategy
self.addEventListener('fetch', event => {
    const request = event.request;
    const url = new URL(request.url);

    // Skip non-GET requests and chrome-extension requests
    if (request.method !== 'GET' || url.protocol === 'chrome-extension:') {
        return;
    }

    // Handle PWA app requests
    if (url.pathname.startsWith('/health_pwa')) {
        if (url.pathname.startsWith('/health_pwa/api/') || url.pathname.startsWith('/health_pwa/sync/')) {
            // API requests - Network First with Cache Fallback
            event.respondWith(handleAPIRequest(request));
        } else {
            // Static files - Cache First
            event.respondWith(handleStaticRequest(request));
        }
    }
});

// Handle API requests with Network First strategy
async function handleAPIRequest(request) {
    const url = new URL(request.url);

    try {
        // Try network first
        const response = await fetch(request);

        // Cache successful GET responses for offline use
        if (response.ok && request.method === 'GET') {
            const cache = await caches.open(API_CACHE_NAME);
            cache.put(request, response.clone());
        }

        return response;
    } catch (error) {
        console.log('Network failed, trying cache for:', url.pathname);

        // Network failed, try cache
        const cache = await caches.open(API_CACHE_NAME);
        const cachedResponse = await cache.match(request);

        if (cachedResponse) {
            // Add offline indicator header
            const response = cachedResponse.clone();
            response.headers.set('X-Served-By', 'ServiceWorker-Cache');
            return response;
        }

        // Return offline response for API requests
        return new Response(JSON.stringify({
            success: false,
            error: 'Network unavailable and no cached data',
            offline: true,
            timestamp: new Date().toISOString()
        }), {
            status: 503,
            headers: { 'Content-Type': 'application/json' }
        });
    }
}

// Handle static requests with Cache First strategy
async function handleStaticRequest(request) {
    const cache = await caches.open(CACHE_NAME);
    const cachedResponse = await cache.match(request);

    if (cachedResponse) {
        return cachedResponse;
    }

    try {
        const response = await fetch(request);
        if (response.ok) {
            cache.put(request, response.clone());
        }
        return response;
    } catch (error) {
        console.log('Static request failed:', request.url);

        // Return offline page for navigation requests
        if (request.mode === 'navigate') {
            const offlineResponse = await cache.match(OFFLINE_URL);
            return offlineResponse || new Response('Offline', { status: 503 });
        }

        // Return minimal response for other requests
        return new Response('Offline', { status: 503 });
    }
}

// Background sync for offline actions
self.addEventListener('sync', event => {
    console.log('Background sync triggered:', event.tag);

    if (event.tag === 'health-pwa-sync') {
        event.waitUntil(performBackgroundSync());
    }
});

// Perform background sync
async function performBackgroundSync() {
    try {
        // Get pending sync data from IndexedDB (handled by PouchDB)
        console.log('Performing background sync...');

        // Send message to active clients to trigger sync
        const clients = await self.clients.matchAll();
        clients.forEach(client => {
            client.postMessage({
                type: 'BACKGROUND_SYNC',
                timestamp: new Date().toISOString()
            });
        });

    } catch (error) {
        console.error('Background sync failed:', error);
    }
}

// Push notification handler (for future use)
self.addEventListener('push', event => {
    console.log('Push notification received:', event);

    const options = {
        body: event.data ? event.data.text() : 'New health update available',
        icon: '/health_pwa/static/icons/icon-192.png',
        badge: '/health_pwa/static/icons/icon-96.png',
        vibrate: [200, 100, 200],
        tag: 'health-pwa-notification',
        actions: [
            {
                action: 'open',
                title: 'Open App',
                icon: '/health_pwa/static/icons/icon-96.png'
            },
            {
                action: 'close',
                title: 'Close',
                icon: '/health_pwa/static/icons/icon-96.png'
            }
        ]
    };

    event.waitUntil(
        self.registration.showNotification('Health Mobile', options)
    );
});

// Notification click handler
self.addEventListener('notificationclick', event => {
    console.log('Notification clicked:', event);
    event.notification.close();

    if (event.action === 'open') {
        event.waitUntil(
            clients.matchAll().then(clientList => {
                // Try to focus existing window
                for (const client of clientList) {
                    if (client.url.includes('/health_pwa') && 'focus' in client) {
                        return client.focus();
                    }
                }

                // Open new window if no existing window
                if (clients.openWindow) {
                    return clients.openWindow('/health_pwa');
                }
            })
        );
    }
});

console.log('Health PWA Service Worker loaded successfully');

div.script:
// Auto-retry when back online
window.addEventListener('online', function() {
    setTimeout(function() {
        window.location.reload();
    }, 1000);
});
